        pairs.append((int(lines[i].strip()), lines[i+1].strip()))
    return pairs
def entities(pairs):
    # return list of entities (list of (code,val)) in ENTITIES section
    ents=[];cur=None;insec=None;i=0
    sec=None
    for code,val in pairs:
        if code==0 and val=='SECTION': sec='pending'; continue
